// 解析一行列表字符串，返回一维整数向量
vector<int> parseList(const string& s) {
    vector<int> res;
    stringstream ss(s);
    char ch;
    int num;
    while (ss >> ch) {
        if (ch == '[' || ch == ',' || ch == ' ') {
            continue;
        } else if (ch == ']') {
            break;
        } else {
            ss.putback(ch);
            ss >> num;
            res.push_back(num);
        }
    }
    return res;
}

// 解析二维列表字符串，返回二维整数向量
vector<vector<int>> parse2DList(const string& s) {
    vector<vector<int>> res;
    stringstream ss(s);
    char ch;
    // 跳过开头的'['
    ss >> ch;
    while (true) {
        // 读取下一个字符，可能是'['或']'
        ss >> ch;
        if (ch == ']') {
            break;
        } else if (ch == '[') {
            // 解析一行
            string rowStr;
            getline(ss, rowStr, ']');
            rowStr = "[" + rowStr + "]";
            vector<int> row = parseList(rowStr);
            res.push_back(row);
        }
    }
    return res;
}

int main() {
    string featureMapStr;
    getline(cin, featureMapStr);
    string poolSizeStr;
    getline(cin, poolSizeStr);

    // 解析特征图和池化窗口大小
    vector<vector<int>> featureMap = parse2DList(featureMapStr);
    vector<int> poolSize = parseList(poolSizeStr);

    int n = featureMap.size();
    int w = poolSize[0];
    int h = poolSize[1];

    // 计算输出特征图的尺寸
    int out_h = n / h;
    int out_w = n / w;

    vector<vector<int>> result(out_h, vector<int>(out_w));

    for (int i = 0; i < out_h; i++) {
        for (int j = 0; j < out_w; j++) {
            int start_i = i * h;
            int start_j = j * w;
            int maxVal = featureMap[start_i][start_j];
            // 遍历池化窗口内的所有元素
            for (int ki = 0; ki < h; ki++) {
                for (int kj = 0; kj < w; kj++) {
                    int cur = featureMap[start_i + ki][start_j + kj];
                    if (cur > maxVal) {
                        maxVal = cur;
                    }
                }
            }
            result[i][j] = maxVal;
        }
    }

    // 输出结果
    cout << "[";
    for (int i = 0; i < out_h; i++) {
        cout << "[";
        for (int j = 0; j < out_w; j++) {
            cout << result[i][j];
            if (j < out_w - 1) {
                cout << ",";
            }
        }
        cout << "]";
        if (i < out_h - 1) {
            cout << ",";
        }
    }
    cout << "]" << endl;

    return 0;
}
